:root { --bg: #100c1c; --panel: #191329; --line: #30264a; --ink: #eee9f8; --muted: #a59bb8; --accent: #ffb547; --pick: #ff3d9a; --ok: #9bf06a; --warn: #ff9d6c; }
* { box-sizing: border-box; }
