.st-more { position: relative; } .st-more summary { list-style: none; cursor: pointer; padding: 5px 12px; background: #2a2040; border: 1px solid var(--line); border-radius: 8px; } .st-more summary::-webkit-details-marker { display: none; } .st-more div { position: absolute; z-index: 30; top: 38px; left: 0; display: grid; gap: 4px; padding: 6px; background: var(--panel); border: 1px solid var(--line); border-radius: 8px; white-space: nowrap; }
