.st-tabs { display: flex; } .st-tabs button { border-radius: 0; } .st-tabs button:first-child { border-radius: 8px 0 0 8px; } .st-tabs button:last-child { border-radius: 0 8px 8px 0; border-left: 0; } .st-tabs button.on { background: var(--accent); border-color: var(--accent); color: #17120a; font-weight: 600; }
