.pt { display: flex; gap: 2px; margin: 0 -14px 12px; padding: 0 14px; border-bottom: 1px solid var(--line); position: sticky; top: -14px; z-index: 8; background: var(--panel); } .pt button { flex: 1; padding: 7px 4px; background: none; border: 0; border-bottom: 2px solid transparent; border-radius: 0; color: var(--muted); white-space: nowrap; } .pt button.on { color: var(--ink); border-bottom-color: var(--accent); font-weight: 600; } .pt b { font-weight: 700; } .pt button.waiting { color: var(--accent); } .pane[hidden] { display: none; }
